  }
}

// Factory Method - один продукт:
interface ButtonFactory { public function create(): Button; }
class WinFactory implements ButtonFactory {
  public function create(): Button { return new WinButton(); }
}

interface Payment { public function pay(int $sum): void; }
class ByCard implements Payment { public function pay(int $s): void {} }
class Order {
  public function __construct(private Payment $p) {}
  public function checkout(int $s): void { $this->p->pay($s); } // способ подставили снаружи
}

interface Observer { public function update(string $event): void; }
class Subject {
  private array $obs = [];
  public function attach(Observer $o): void { $this->obs[] = $o; } // подписка
  public function notify(string $e): void {
    foreach ($this->obs as $o) { $o->update($e); } // оповещаем всех
  }
}

interface Response { public function body(): string; }
class GzipDecorator implements Response {
  public function __construct(private Response $r) {} // оборачиваем другой Response
  public function body(): string { return gzencode($this->r->body()); } // добавляем сжатие
}

